  expect(missingStyle.fontSize).toBeLessThan(knownStyle.fontSize);
  await expect(page.locator(".member-total")).toHaveText([
    "Amount unavailable",
    "Amount unavailable",
  ]);
  amount = "90071992547409939007199254740993.123456789";
  await page.reload();
